package edu.uiu.aoop.careerforge.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import org.springframework.http.HttpHeaders; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter {
 private final JwtService jwt; public JwtAuthenticationFilter(JwtService jwt){this.jwt=jwt;}
 @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain) throws ServletException,IOException { String header=req.getHeader(HttpHeaders.AUTHORIZATION); if(header!=null&&header.startsWith("Bearer ")) { try { AppPrincipal p=jwt.parse(header.substring(7)); var auth=new UsernamePasswordAuthenticationToken(p,null,java.util.List.of(new SimpleGrantedAuthority("ROLE_"+p.role().name().toUpperCase()))); SecurityContextHolder.getContext().setAuthentication(auth); } catch(Exception ignored) { } } chain.doFilter(req,res); }
}
